insert into public.drills (id, dir, topic, sort, context, source, for_author, focus) values
('dr-20260928-ke-m1','KR→EN','marketing',1,'러닝 앱 신규 기능 출시 푸시','이제 달린 길이 지도에 그림으로 남아요. 오늘 저녁, 첫 그림을 그려 보세요.',(select email from public.members where display_name='희주'),'둘째 문장(행동 유도)까지 빠짐없이'),
('dr-20260928-ke-m2','KR→EN','marketing',2,'동네 꽃집 인스타그램 소개','매주 목요일, 제철 꽃이 들어와요. 이번 주는 작약입니다.',null,''),
('dr-20260928-ke-m3','KR→EN','marketing',3,'안경원 매장 입구 문구','써 보기 전엔 몰라요. 스무 개쯤 써 보셔도 괜찮아요.',null,''),
('dr-20260928-ke-b1','KR→EN','business',1,'고객에게 배송 지연 안내 메일','주문하신 상품의 입고가 늦어져 발송이 3일가량 지연될 예정입니다. 불편을 드려 죄송합니다.',null,''),
('dr-20260928-ke-b2','KR→EN','business',2,'신입 동료를 팀에 소개하는 사내 메일','오늘부터 마케팅팀에 합류한 박서연 님을 소개합니다. 따뜻하게 맞아 주세요.',null,''),
('dr-20260928-ke-b3','KR→EN','business',3,'거래처에 단가 인상 안내','원자재 가격 상승으로 다음 달부터 단가를 5% 조정하게 되었습니다. 양해 부탁드립니다.',null,''),
('dr-20260928-ke-d1','KR→EN','daily',1,'친구에게 주말 저녁 초대','이번 주말에 약속 있어? 없으면 우리 집에서 저녁 먹자. 가족들 다 모이는 날이라 북적북적할 거야.',(select email from public.members where display_name='희주'),'약속은 plans, 모임은 get-together'),
('dr-20260928-ke-d2','KR→EN','daily',2,'비 오는 날 친구에게 메시지','우산 챙겼어? 오후에 비 온대. 괜히 새 신발 신지 말고.',null,''),
('dr-20260928-ke-d3','KR→EN','daily',3,'카페에서 친구가 계산하려 할 때','야, 이번엔 내가 낼게. 지난번에 네가 샀잖아.',null,''),
('dr-20260928-ke-t1','KR→EN','travel',1,'호텔 프런트에 전화','여기 1203호인데요, 방 에어컨이 안 켜져요. 사람 좀 보내 주실 수 있을까요?',(select email from public.members where display_name='희주'),'호텔에서 내가 묵는 방은 my room'),
('dr-20260928-ke-t2','KR→EN','travel',2,'기차역 매표소','부산 가는 제일 빠른 기차로 두 장 주세요. 자리는 붙어 있으면 좋겠어요.',null,''),
('dr-20260928-ke-t3','KR→EN','travel',3,'박물관에서 오디오 가이드 빌리기','한국어 오디오 가이드도 있나요? 신분증을 맡겨야 하나요?',null,''),
('dr-20260928-ek-m1','EN→KR','marketing',1,'전기자전거 공유 서비스 광고','Skip the traffic. Not the scenery.',null,''),
('dr-20260928-ek-m2','EN→KR','marketing',2,'캠핑 용품 브랜드 SNS','Pack light. Stay longer.',null,''),
('dr-20260928-ek-m3','EN→KR','marketing',3,'온라인 서점 이메일 제목','Your next favorite book is hiding in here.',null,''),
('dr-20260928-ek-b1','EN→KR','business',1,'회의 일정 조율 메일','Does Thursday afternoon work for you? If not, I''m flexible next week.',null,''),
('dr-20260928-ek-b2','EN→KR','business',2,'프로젝트 마감 후 팀에 감사','Couldn''t have pulled this off without you all. Drinks are on me Friday.',null,''),
('dr-20260928-ek-b3','EN→KR','business',3,'고객 불만 메일에 첫 답장','Thanks for flagging this. We''re looking into it and will get back to you within 24 hours.',null,''),
('dr-20260928-ek-d1','EN→KR','daily',1,'친구의 새 머리를 보고','Okay, the new haircut really suits you.',null,''),
('dr-20260928-ek-d2','EN→KR','daily',2,'고민을 털어놓는 친구에게','You don''t have to decide tonight. Sleep on it.',null,''),
('dr-20260928-ek-d3','EN→KR','daily',3,'주말 계획을 묻는 친구에게','Nothing much. Just gonna stay in and binge a show.',null,''),
('dr-20260928-ek-t1','EN→KR','travel',1,'호텔 체크인 때 직원 안내','Your room''s ready. The Wi-Fi password is on the back of your key card.',null,''),
('dr-20260928-ek-t2','EN→KR','travel',2,'지하철 안내 방송','Please stand clear of the closing doors.',null,''),
('dr-20260928-ek-t3','EN→KR','travel',3,'여행지 가게 점원의 말','Cash only, I''m afraid. There''s an ATM just around the corner.',null,'');
insert into public.drill_models (drill_id, best, alternatives, notes) values
('dr-20260928-ke-m1','Your runs now leave a picture on the map. Draw your first one tonight.','["Every run now turns into a drawing on the map. Start your first tonight.", "Now your route becomes art on the map. Sketch your first one this evening."]'::jsonb,'[{"phrase": "두 번째 문장 = 행동 유도(CTA)", "why": "''그려 보세요''가 행동을 부르는 문장이에요. 빠뜨리면 기능 소개만 남아요. 두 문장을 다 옮겼는지 마지막에 확인해요."}, {"phrase": "그려 보세요 → Draw your first one", "why": "''~해 보세요''를 try to로 옮기지 않아요. 영어 카피는 동사 명령형으로 바로 시작해요."}, {"phrase": "오늘 저녁 → tonight", "why": "this evening보다 tonight이 짧고 카피에 잘 붙어요."}]'::jsonb),
('dr-20260928-ke-m2','Fresh seasonal blooms arrive every Thursday. This week: peonies.','["New seasonal flowers land every Thursday. This week, it''s peonies.", "Every Thursday brings what''s in season. This week, peonies."]'::jsonb,'[{"phrase": "이번 주는 작약입니다 → This week: peonies.", "why": "''~입니다''를 is로 살리면 늘어져요. SNS 카피는 콜론으로 짧게 끊어요."}, {"phrase": "제철 꽃 → seasonal blooms", "why": "flower보다 bloom이 꽃집 카피에서 더 감각적으로 들려요."}]'::jsonb),
('dr-20260928-ke-m3','You won''t know until you try them on. Try twenty. We don''t mind.','["You can''t tell until they''re on your face. Go ahead, try twenty.", "The right pair only shows up when you try it on. Try as many as you like."]'::jsonb,'[{"phrase": "써 보다 → try on", "why": "옷·안경을 걸쳐 볼 때는 try on이에요. wear로 옮기면 ''착용하고 다니다''가 돼요."}, {"phrase": "괜찮아요 → We don''t mind", "why": "It''s okay보다 가게 쪽 목소리가 살아나요. 손님 마음을 편하게 해 주는 말투예요."}]'::jsonb),
('dr-20260928-ke-b1','Due to a delay in restocking, your order will ship about three days later than expected. We apologize for the inconvenience.','["Your order is running about three days behind because the item is late coming into stock. We''re sorry for the wait.", "We expect your order to ship about three days late, as the item is arriving later than planned. Our apologies."]'::jsonb,'[{"phrase": "입고가 늦어져 → a delay in restocking", "why": "입고를 warehousing으로 옮기면 물류 용어처럼 딱딱해요. 고객에게는 restock, come into stock이 쉬워요."}, {"phrase": "지연될 예정입니다 → will ship … later than expected", "why": "''예정''을 is scheduled to be delayed로 옮기면 어색해요. 언제 보내는지를 중심으로 써요."}]'::jsonb),
('dr-20260928-ke-b2','Please join me in welcoming Seoyeon Park, who joins the marketing team today.','["I''m pleased to introduce Seoyeon Park, who joins our marketing team today. Please give Seoyeon a warm welcome.", "Starting today, Seoyeon Park is part of the marketing team. Please make Seoyeon feel at home."]'::jsonb,'[{"phrase": "따뜻하게 맞아 주세요 → Please join me in welcoming", "why": "영어 사내 공지의 정형 표현이에요. Please welcome warmly는 어순이 어색해요."}, {"phrase": "~님", "why": "''님''은 옮기지 않아요. 영어에서는 이름만 불러도 예의 바른 표현이에요."}]'::jsonb),
('dr-20260928-ke-b3','Due to rising material costs, we will be adjusting our unit prices by 5% starting next month. We appreciate your understanding.','["As raw material costs have gone up, our unit prices will increase by 5% from next month. Thank you for your understanding.", "Starting next month, unit prices will be adjusted by 5% to reflect higher material costs. We hope you understand."]'::jsonb,'[{"phrase": "조정하게 되었습니다 → will be adjusting", "why": "''~하게 되었다''를 it has become으로 옮기지 않아요. 결정 사항은 will be + -ing로 담담하게 알려요."}, {"phrase": "양해 부탁드립니다 → We appreciate your understanding", "why": "Please understand는 명령처럼 들려요. 감사 표현으로 바꾸는 게 영어 비즈니스 관례예요."}]'::jsonb),
('dr-20260928-ke-d1','Got any plans this weekend? If not, come over for dinner. The whole family''s getting together, so it''ll be a full house.','["Are you free this weekend? Come have dinner at my place. It''s a family get-together, so it''ll be lively.", "Doing anything this weekend? If you''re free, join us for dinner. My whole family will be there, so it''ll be busy in the best way."]'::jsonb,'[{"phrase": "약속 → plans", "why": "date는 연인과의 데이트를 떠올리게 해요. 친구와의 약속은 plans예요."}, {"phrase": "가족들 다 모이는 → getting together", "why": "family meeting은 가족회의처럼 들려요. 모임은 get-together, gathering이에요."}, {"phrase": "북적북적 → a full house", "why": "crowded는 불편한 느낌이 있어요. a full house, lively가 반가운 북적임이에요."}]'::jsonb),
('dr-20260928-ke-d2','Got your umbrella? It''s supposed to rain this afternoon. Maybe skip the new shoes today.','["Did you grab an umbrella? Rain''s coming this afternoon. I''d save the new shoes for another day.", "Bring an umbrella, it''s meant to rain later. Don''t wear your new shoes!"]'::jsonb,'[{"phrase": "비 온대 → It''s supposed to rain", "why": "들은 소식을 전하는 ''~한대''는 be supposed to, be meant to예요. It will rain은 단정적이에요."}, {"phrase": "괜히 ~하지 말고 → Maybe skip", "why": "''괜히''를 needlessly로 옮기면 어색해요. 부드러운 권유는 Maybe skip, I''d save ~ for another day."}]'::jsonb),
('dr-20260928-ke-d3','No way, this one''s on me. You got it last time.','["Put your wallet away, it''s my turn. You paid last time.", "I''ve got this one. You treated me last time."]'::jsonb,'[{"phrase": "내가 낼게 → this one''s on me", "why": "I will pay도 맞지만 친구 사이에선 on me, I''ve got this가 자연스러워요."}, {"phrase": "네가 샀잖아 → You got it last time", "why": "계산은 buy보다 get, pay, treat으로 말해요."}]'::jsonb),
('dr-20260928-ke-t1','Hi, this is room 1203. The air conditioning in my room won''t turn on. Could you send someone up?','["Hello, I''m calling from room 1203. My AC isn''t working. Would you mind sending someone to take a look?", "This is 1203. The air conditioner in my room isn''t turning on. Could someone come and check it?"]'::jsonb,'[{"phrase": "방 → my room", "why": "직원에게는 내가 묵는 방을 my room이라고 해요. the room은 어느 방인지 흐려져요."}, {"phrase": "안 켜져요 → won''t turn on", "why": "won''t는 ''아무리 해도 안 된다''는 느낌이라 고장 신고에 딱이에요."}, {"phrase": "사람 좀 보내 → send someone up", "why": "호텔에서 객실로 직원을 보내 달라고 할 때 send someone up을 자주 써요."}]'::jsonb),
('dr-20260928-ke-t2','Two tickets for the next train to Busan, please. Could we sit together?','["I''d like two tickets on the next train to Busan, with seats side by side if possible.", "Two for the next train to Busan, please. Seats together, if you have them."]'::jsonb,'[{"phrase": "제일 빠른 기차 → the next train", "why": "가장 먼저 출발하는 기차라면 fastest가 아니라 next, earliest예요. fastest는 속도가 빠른 열차예요."}, {"phrase": "붙어 있으면 → together, side by side", "why": "attached는 물건이 붙어 있을 때 써요. 자리는 together, side by side."}]'::jsonb),
('dr-20260928-ke-t3','Do you have an audio guide in Korean? Do I need to leave an ID?','["Is the audio guide available in Korean? Do you need me to leave some ID?", "Do you offer a Korean audio guide? And should I leave my ID with you?"]'::jsonb,'[{"phrase": "신분증을 맡기다 → leave an ID", "why": "''맡기다''를 entrust로 옮기면 너무 무거워요. 잠깐 두고 가는 건 leave예요."}, {"phrase": "~도 있나요 → Do you have ~", "why": "''도''를 also로 옮기면 어색해요. 있는지 묻는 거라 Do you have, available이 자연스러워요."}]'::jsonb),
('dr-20260928-ek-m1','막히는 길은 건너뛰고, 풍경은 그대로.','["차는 막혀도, 풍경은 놓치지 말고.", "정체는 빼고, 풍경만 담아요."]'::jsonb,'[{"phrase": "Skip ~. Not ~.", "why": "같은 동사를 두 번 쓰는 대구예요. 한국어도 ''~은 건너뛰고, ~은 그대로''처럼 짝을 맞춰야 리듬이 살아요."}, {"phrase": "traffic → 막히는 길", "why": "''교통''으로 옮기면 뜻이 흐려요. 광고에서 traffic은 정체예요."}]'::jsonb),
('dr-20260928-ek-m2','가볍게 챙기고, 오래 머물러요.','["짐은 가볍게, 머무름은 길게.", "덜 챙길수록 더 오래."]'::jsonb,'[{"phrase": "명령형 두 개", "why": "''가볍게 싸라''처럼 명령형으로 옮기면 딱딱해요. 해요체나 명사형 대구로 부드럽게 바꿔요."}, {"phrase": "Stay longer", "why": "''더 오래 머무르세요''도 되지만, 짐과 머무름을 맞세우면 더 기억에 남아요."}]'::jsonb),
('dr-20260928-ek-m3','다음 인생 책, 여기 숨어 있어요.','["곧 가장 좋아하게 될 책이 이 안에 있어요.", "아직 못 만난 최애 책, 여기서 찾아보세요."]'::jsonb,'[{"phrase": "Your next favorite book → 다음 인생 책", "why": "''당신의 다음 가장 좋아하는 책''은 번역투예요. ''인생 책''이 뜻과 온도를 같이 담아요."}, {"phrase": "Your → 생략", "why": "광고에서 ''당신의''는 거리감이 생겨요. 한국어는 소유격을 빼도 통해요."}]'::jsonb),
('dr-20260928-ek-b1','목요일 오후 괜찮으실까요? 어려우시면 다음 주는 언제든 맞출 수 있습니다.','["목요일 오후 시간 되실까요? 안 되시면 다음 주 중 편하신 때로 잡겠습니다.", "목요일 오후는 어떠세요? 어려우시면 다음 주에는 일정 조정이 가능합니다."]'::jsonb,'[{"phrase": "work for you → 괜찮으실까요", "why": "일정이 맞는지 묻는 관용 표현이에요. ''작동하다''와는 상관없어요."}, {"phrase": "I''m flexible → 언제든 맞출 수 있습니다", "why": "''유연합니다''는 번역투예요. 상대에게 맞추겠다는 뜻으로 풀어요."}]'::jsonb),
('dr-20260928-ek-b2','여러분 아니었으면 못 해냈을 거예요. 금요일 한잔은 제가 쏠게요.','["다들 덕분에 무사히 마쳤어요. 금요일 술은 제가 살게요.", "여러분 없었으면 해내지 못했을 거예요. 금요일에 한잔해요, 제가 낼게요."]'::jsonb,'[{"phrase": "pull off → 해내다", "why": "어려운 일을 결국 성공시켰다는 뜻이에요."}, {"phrase": "Couldn''t have ~ without you", "why": "''당신 없이는 할 수 없었을 것이다''는 딱딱해요. ''여러분 아니었으면''으로 시작해요."}, {"phrase": "Drinks are on me → 제가 쏠게요", "why": "on me는 내가 낸다는 뜻이에요. 팀 분위기에는 ''쏠게요''가 맞는 격이에요."}]'::jsonb),
('dr-20260928-ek-b3','알려 주셔서 감사합니다. 지금 확인하고 있으며, 24시간 안에 다시 연락드리겠습니다.','["말씀해 주셔서 감사합니다. 내용을 살펴보고 하루 안에 회신드리겠습니다.", "짚어 주셔서 감사합니다. 확인 중이며 24시간 이내에 답변드리겠습니다."]'::jsonb,'[{"phrase": "flag → 알려 주다, 짚어 주다", "why": "''깃발을 달다''가 아니라 문제를 알려 줬다는 뜻이에요."}, {"phrase": "look into → 확인하다", "why": "고객 응대에서는 ''들여다보다''보다 ''확인하다''가 격에 맞아요."}, {"phrase": "get back to you → 다시 연락드리다", "why": "회신하겠다는 관용 표현이에요."}]'::jsonb),
('dr-20260928-ek-d1','와, 머리 진짜 잘 어울린다.','["새로 자른 머리 완전 잘 어울려.", "머리 바꿨네? 딱 네 스타일이다."]'::jsonb,'[{"phrase": "Okay, → 와", "why": "여기서 Okay는 ''알겠어''가 아니라 감탄의 시작이에요."}, {"phrase": "suits you → 잘 어울린다", "why": "''너에게 맞다''가 아니라 잘 어울린다는 뜻이에요."}]'::jsonb),
('dr-20260928-ek-d2','오늘 밤에 정할 필요 없어. 하룻밤 자고 생각해 봐.','["지금 바로 결정 안 해도 돼. 자고 일어나서 다시 생각해.", "급하게 정하지 마. 하루 푹 자고 생각해 봐."]'::jsonb,'[{"phrase": "Sleep on it → 하룻밤 자고 생각해 봐", "why": "결정을 하루 미루고 차분히 생각하라는 관용구예요."}, {"phrase": "You don''t have to", "why": "''너는 ~할 필요가 없다''에서 ''너는''은 빼요. 한국어 구어는 주어를 생략해요."}]'::jsonb),
('dr-20260928-ek-d3','별거 없어. 그냥 집에서 드라마 몰아 보려고.','["딱히 없어. 집콕하면서 시리즈 정주행할 거야.", "아무 계획 없어. 집에서 드라마나 몰아 볼까 해."]'::jsonb,'[{"phrase": "stay in → 집에 있다, 집콕", "why": "''안에 머물다''가 아니라 외출하지 않는다는 뜻이에요."}, {"phrase": "binge → 몰아 보다, 정주행", "why": "binge-watch의 줄임말이에요. ''정주행'', ''몰아 보기''가 딱이에요."}]'::jsonb),
('dr-20260928-ek-t1','객실 준비되어 있습니다. 와이파이 비밀번호는 카드 키 뒷면에 적혀 있어요.','["방은 바로 쓰실 수 있습니다. 와이파이 비밀번호는 카드 키 뒤에 있어요.", "객실 준비가 끝났습니다. 와이파이 비밀번호는 카드 키 뒷면을 확인해 주세요."]'::jsonb,'[{"phrase": "Your room''s ready → 객실 준비되어 있습니다", "why": "''당신의 방''은 빼요. 호텔 안내에서는 ''객실''이라고 해요."}, {"phrase": "on the back of → 뒷면에 적혀 있어요", "why": "''뒤에 있다''보다 ''적혀 있다''가 무엇이 어디 쓰여 있는지 분명해요."}]'::jsonb),
('dr-20260928-ek-t2','출입문 닫습니다. 문에서 한 걸음 물러서 주십시오.','["문이 닫힙니다. 문에서 떨어져 주시기 바랍니다.", "출입문이 닫히니 물러서 주십시오."]'::jsonb,'[{"phrase": "stand clear of → 물러서다, 떨어지다", "why": "닿지 않게 떨어지라는 뜻이에요."}, {"phrase": "안내 방송의 격", "why": "실제 지하철처럼 ''~닫습니다'', ''~주십시오'' 같은 방송 말투를 써요. 해요체는 현장 방송과 격이 안 맞아요."}]'::jsonb),
('dr-20260928-ek-t3','죄송하지만 현금만 받아요. 모퉁이 돌면 바로 ATM이 있어요.','["현금 결제만 가능해서 죄송해요. 코너만 돌면 현금인출기가 있어요.", "아쉽게도 현금만 돼요. 모퉁이 바로 옆에 ATM 있어요."]'::jsonb,'[{"phrase": "I''m afraid → 죄송하지만, 아쉽게도", "why": "''두렵다''가 아니에요. 안 좋은 소식을 부드럽게 전하는 말이에요."}, {"phrase": "just around the corner → 모퉁이 돌면 바로", "why": "''모퉁이 주변''이 아니라 아주 가깝다는 뜻이에요."}]'::jsonb);
insert into public.weekly_reports (author, week_of, body) values ((select email from public.members where display_name='희주'), '2026-09-28', '지난 한 주 동안 번역 17개를 제출하고 피드백을 13번 요청했어요.
insert into public.copy_briefs (id, week, title, product, target, tone, rules, sort) values
('cb-20260928-1','2026-09-28','Loomwell · 리사이클 울 니트','버려진 울 스웨터를 풀어 다시 짠 니트. 한 벌에 헌 스웨터 두 벌이 들어가요. 색은 원래 실 색 그대로라 같은 색이 거의 없어요.','날이 추워지면 새 옷보다 오래 입을 옷을 찾는 20~30대','다정하고 담백하게. 환경 이야기를 앞세우기보다 ''이 옷의 지난 이야기''를 들려줘요.','인스타그램 캡션 2문장 이내, 해시태그 없이. sustainable, eco-friendly는 쓰지 않아요.',1),
('cb-20260928-2','2026-09-28','Tidebound · 섬 여행 페리 예약','남해 섬 30곳의 페리 시간표와 예약을 한 앱에서. 출항 2시간 전까지 취소하면 전액 환불.','주말마다 어디 갈지 고민하는 도시 직장인','위트 있게. 지하철에서 지나가다 보고 피식 웃게.','지하철역 포스터 헤드라인 6단어 이하. adventure, paradise는 쓰지 않아요.',2),
('cb-20260928-3','2026-09-28','Oat & Ember · 향초 정기구독','매달 계절에 맞는 향초 하나를 집으로 보내요. 이번 달은 구운 귀리와 무화과 향. 한 달에 18달러, 언제든 건너뛰기 가능.','퇴근 후 집을 쉬는 공간으로 만들고 싶은 사람','고급스럽지만 조용하게. 향을 형용사 대신 장면으로 보여 줘요.','이메일 제목(영어 45자 이내) + 프리헤더 1줄. exclusive, luxury는 쓰지 않아요.',3)
